INSERT INTO lp_app_settings (id, latest_version_code, min_supported_version_code, update_message, maintenance_mode, maintenance_message, default_language, default_country, play_store_url, web_url, support_email, privacy_url, terms_url, medical_disclaimer, emergency_numbers, share_text) VALUES
  (true, 1, 1, '{"en":"A new version of Life-Stage Parenting is available.","bn":"লাইফ-স্টেজ প্যারেন্টিংয়ের নতুন সংস্করণ এসেছে।"}'::jsonb, false, '{"en":"We are improving the app. Your records are safe; please try again soon.","bn":"আমরা অ্যাপটি উন্নত করছি। আপনার তথ্য নিরাপদ আছে; একটু পরে আবার চেষ্টা করুন।"}'::jsonb, 'bn', 'BD', 'https://play.google.com/store/apps/details?id=com.cryptdox.lifestageparenting', NULL, NULL, NULL, NULL, '{"en":"This app helps you learn and keep records. It does not diagnose or treat, and it does not replace your doctor, midwife or health worker. In an emergency, go to the nearest hospital or call for help at once.","bn":"এই অ্যাপ আপনাকে জানতে ও তথ্য রাখতে সাহায্য করে। এটি রোগ নির্ণয় বা চিকিৎসা করে না, এবং আপনার ডাক্তার, মিডওয়াইফ বা স্বাস্থ্যকর্মীর বিকল্প নয়। জরুরি অবস্থায় সাথে সাথে নিকটস্থ হাসপাতালে যান বা সাহায্যের জন্য ফোন করুন।"}'::jsonb, '{"BD":[{"label":{"en":"National emergency (ambulance, fire, police)","bn":"জাতীয় জরুরি সেবা (অ্যাম্বুলেন্স, ফায়ার, পুলিশ)"},"number":"999"},{"label":{"en":"Shastho Batayon health helpline","bn":"স্বাস্থ্য বাতায়ন হেল্পলাইন"},"number":"16263"}]}'::jsonb, '{"en":"Life-Stage Parenting: a guide for every stage, from planning a baby to the teenage years.","bn":"লাইফ-স্টেজ প্যারেন্টিং: সন্তান পরিকল্পনা থেকে কৈশোর পর্যন্ত প্রতিটি ধাপের সঙ্গী।"}'::jsonb)
