  ('early_childhood', 4, '{"en":"Early Childhood","bn":"প্রারম্ভিক শৈশব"}'::jsonb, '{"en":"2 – 4 years","bn":"২ – ৪ বছর"}'::jsonb, '{"en":"Language, emotions, self-care, play and first manners.","bn":"ভাষা, আবেগ, নিজের যত্ন, খেলা ও প্রথম আদব।"}'::jsonb, '🧸', '#e9c46a', 730, 1461, 4),
