  ('adolescence', 7, '{"en":"Teenage Years","bn":"কৈশোর"}'::jsonb, '{"en":"13 – 19 years","bn":"১৩ – ১৯ বছর"}'::jsonb, '{"en":"Health, wellbeing, identity, values and the move to adulthood, with trust.","bn":"আস্থার সাথে স্বাস্থ্য, মানসিক সুস্থতা, পরিচয়, মূল্যবোধ ও প্রাপ্তবয়স্কতার পথে।"}'::jsonb, '🧑‍🎓', '#273c75', 4748, 7305, 7)
