INSERT INTO lp_vaccines (key, short_name, name, protects_against, common_reactions, notes, sort_order) VALUES
  ('bcg', 'BCG', '{"en":"BCG","bn":"বিসিজি"}'::jsonb, '{"en":"Tuberculosis (especially severe forms in young children)","bn":"যক্ষ্মা (বিশেষ করে শিশুদের মারাত্মক যক্ষ্মা)"}'::jsonb, '{"en":"A small bump that may become a sore and heal into a small scar over weeks.","bn":"ছোট একটি ফোলা, যা কয়েক সপ্তাহে ঘা হয়ে ছোট দাগ রেখে সেরে যায়।"}'::jsonb, '{}'::jsonb, 1),
  ('penta', 'Penta', '{"en":"Pentavalent (DPT-HepB-Hib)","bn":"পেন্টাভ্যালেন্ট (ডিপিটি-হেপবি-হিব)"}'::jsonb, '{"en":"Diphtheria, whooping cough, tetanus, hepatitis B, Haemophilus influenzae type b","bn":"ডিফথেরিয়া, হুপিংকাশি, ধনুষ্টংকার, হেপাটাইটিস-বি, হিমোফিলাস ইনফ্লুয়েঞ্জা-বি"}'::jsonb, '{"en":"Mild fever, fussiness, redness or swelling where the injection was given.","bn":"হালকা জ্বর, অস্থিরতা, ইনজেকশনের জায়গা লাল বা ফোলা।"}'::jsonb, '{}'::jsonb, 2),
  ('opv', 'OPV', '{"en":"Oral polio vaccine (bOPV)","bn":"মুখে খাওয়ার পোলিও টিকা (বিওপিভি)"}'::jsonb, '{"en":"Polio","bn":"পোলিও"}'::jsonb, '{}'::jsonb, '{}'::jsonb, 3),
  ('fipv', 'fIPV', '{"en":"Fractional inactivated polio vaccine (fIPV)","bn":"এফআইপিভি (ইনজেকশনের পোলিও টিকা)"}'::jsonb, '{"en":"Polio","bn":"পোলিও"}'::jsonb, '{}'::jsonb, '{}'::jsonb, 4),
  ('pcv', 'PCV', '{"en":"Pneumococcal conjugate vaccine (PCV)","bn":"নিউমোকক্কাল কনজুগেট টিকা (পিসিভি)"}'::jsonb, '{"en":"Pneumococcal pneumonia, meningitis and blood infection","bn":"নিউমোকক্কাল নিউমোনিয়া, মেনিনজাইটিস ও রক্তের সংক্রমণ"}'::jsonb, '{}'::jsonb, '{}'::jsonb, 5),
  ('mr', 'MR', '{"en":"Measles-rubella (MR)","bn":"হাম-রুবেলা (এমআর)"}'::jsonb, '{"en":"Measles and rubella","bn":"হাম ও রুবেলা"}'::jsonb, '{"en":"Mild fever or a light rash 1–2 weeks later can happen.","bn":"১–২ সপ্তাহ পরে হালকা জ্বর বা হালকা র‍্যাশ হতে পারে।"}'::jsonb, '{}'::jsonb, 6),
  ('tcv', 'TCV', '{"en":"Typhoid conjugate vaccine (TCV)","bn":"টাইফয়েড কনজুগেট টিকা (টিসিভি)"}'::jsonb, '{"en":"Typhoid fever","bn":"টাইফয়েড জ্বর"}'::jsonb, '{}'::jsonb, '{}'::jsonb, 7),
  ('hpv', 'HPV', '{"en":"HPV vaccine","bn":"এইচপিভি টিকা"}'::jsonb, '{"en":"Human papillomavirus, the main cause of cervical cancer","bn":"হিউম্যান প্যাপিলোমা ভাইরাস — জরায়ুমুখ ক্যান্সারের প্রধান কারণ"}'::jsonb, '{}'::jsonb, '{}'::jsonb, 8),
  ('td', 'Td', '{"en":"Td (tetanus-diphtheria) for women","bn":"নারীদের টিডি (ধনুষ্টংকার-ডিফথেরিয়া) টিকা"}'::jsonb, '{"en":"Tetanus and diphtheria; protects the mother and the newborn from tetanus","bn":"ধনুষ্টংকার ও ডিফথেরিয়া; মা ও নবজাতককে ধনুষ্টংকার থেকে রক্ষা করে"}'::jsonb, '{}'::jsonb, '{}'::jsonb, 9)
INSERT INTO lp_vaccine_schedules (key, country, kind, name, notes, effective_from, version, source_key, is_default, review_status) VALUES
  ('bd_epi', 'BD', 'national', '{"en":"Bangladesh EPI (national)","bn":"বাংলাদেশ ইপিআই (জাতীয় টিকাদান কর্মসূচি)"}'::jsonb, '{"en":"Free at government EPI centres. Always follow the dates on your child''s vaccination card; a private doctor''s schedule may add other vaccines.","bn":"সরকারি ইপিআই কেন্দ্রে বিনামূল্যে। সবসময় সন্তানের টিকা কার্ডের তারিখ মেনে চলুন; প্রাইভেট ডাক্তার অন্য টিকাও যোগ করতে পারেন।"}'::jsonb, NULL, 1, 'who_bgd_schedule', true, 'in_review'::lp_review_status)
