INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, sections, min_day, max_day, review_status, sort_order) VALUES
  ('emergency-any-age', 'emergency', 'scientific', 'family', 'emergency', 'consensus', '🚨', '{"en":"Go to hospital now — any age","bn":"এখনই হাসপাতালে যান — যেকোনো বয়সে"}'::jsonb, '{"en":"These signs need emergency care immediately.","bn":"এই লক্ষণগুলো দেখা দিলে সাথে সাথে জরুরি চিকিৎসা দরকার।"}'::jsonb, '{"signs":{"en":["Not responding, or very hard to wake","Struggling to breathe, or lips/face turning blue","A fit (convulsion), especially a first one or one longer than 5 minutes","Swelling of the face or lips with trouble breathing (severe allergy)","Heavy bleeding that does not stop with pressure","Swallowed poison, medicine, a battery or chemicals","A serious burn, a near-drowning or a bad head injury"],"bn":["সাড়া দিচ্ছে না, বা জাগানো খুব কঠিন","শ্বাস নিতে কষ্ট, বা ঠোঁট/মুখ নীল হয়ে যাচ্ছে","খিঁচুনি — বিশেষ করে প্রথমবার বা ৫ মিনিটের বেশি স্থায়ী","মুখ বা ঠোঁট ফুলে শ্বাসকষ্ট (মারাত্মক অ্যালার্জি)","চাপ দিলেও না থামা অতিরিক্ত রক্তপাত","বিষ, ওষুধ, ব্যাটারি বা রাসায়নিক গিলে ফেলেছে","মারাত্মক পোড়া, পানিতে ডোবা বা মাথায় গুরুতর আঘাত"]},"do_now":{"en":["Call 999 or go to the nearest hospital now","Keep the person warm and lying on their side if they are not responding but breathing","Take any medicine or packet they swallowed with you"],"bn":["এখনই ৯৯৯-এ ফোন করুন বা নিকটস্থ হাসপাতালে যান","সাড়া না দিলেও শ্বাস নিলে উষ্ণ রাখুন ও কাত করে শুইয়ে দিন","যে ওষুধ বা প্যাকেট গিলেছে তা সাথে নিয়ে যান"]},"avoid":{"en":["Do not wait to see if it gets better","Do not give food, drink or home remedies to someone who is fitting or not responding","Do not make them vomit after swallowing a chemical or battery"],"bn":["ভালো হয় কিনা দেখার জন্য অপেক্ষা করবেন না","খিঁচুনি চলাকালীন বা সাড়া না দিলে খাবার, পানীয় বা ঘরোয়া ওষুধ দেবেন না","রাসায়নিক বা ব্যাটারি গিললে বমি করানোর চেষ্টা করবেন না"]}}'::jsonb, 0, NULL, 'in_review'::lp_review_status, 1),
  ('emergency-young-infant', 'emergency', 'scientific', 'shared', 'emergency', 'guideline', '👶', '{"en":"Newborn danger signs (first 2 months)","bn":"নবজাতকের বিপদচিহ্ন (প্রথম ২ মাস)"}'::jsonb, '{"en":"A young baby with any of these signs needs a hospital today.","bn":"ছোট শিশুর এর যেকোনো একটি লক্ষণ থাকলে আজই হাসপাতালে নিতে হবে।"}'::jsonb, '{"signs":{"en":["Not feeding well, or stopped feeding","Fits (convulsions)","Fast breathing (60 or more breaths a minute)","Chest pulling in strongly with each breath","Temperature 37.5 °C or higher, or below 35.5 °C (feels cold)","Moves only when touched, or does not move at all","Yellow palms and soles, or yellow skin on the first day"],"bn":["ঠিকমতো খাচ্ছে না, বা খাওয়া বন্ধ করেছে","খিঁচুনি","দ্রুত শ্বাস (মিনিটে ৬০ বা তার বেশি)","প্রতিবার শ্বাসে বুক জোরে ভেতরে ঢুকে যাওয়া","তাপমাত্রা ৩৭.৫ °সে বা বেশি, অথবা ৩৫.৫ °সে-এর কম (ঠান্ডা লাগে)","ছুঁলে তবেই নড়ে, বা একদম নড়ে না","হাতের তালু ও পায়ের তলা হলুদ, বা প্রথম দিনেই ত্বক হলুদ"]},"do_now":{"en":["Go to the nearest hospital now","Keep the baby warm — skin-to-skin on the way","Keep breastfeeding on the way if the baby can feed"],"bn":["এখনই নিকটস্থ হাসপাতালে যান","শিশুকে উষ্ণ রাখুন — পথে ত্বকের সাথে ত্বক লাগিয়ে রাখুন","শিশু খেতে পারলে পথেও বুকের দুধ খাওয়াতে থাকুন"]},"avoid":{"en":["Do not wait until the morning","Do not put oil, honey or anything else in the baby''s mouth or on the cord","Do not give medicine unless a doctor prescribed it"],"bn":["সকাল পর্যন্ত অপেক্ষা করবেন না","শিশুর মুখে বা নাভিতে তেল, মধু বা অন্য কিছু দেবেন না","ডাক্তারের পরামর্শ ছাড়া কোনো ওষুধ দেবেন না"]}}'::jsonb, 0, 61, 'in_review'::lp_review_status, 2),
  ('emergency-child-under-5', 'emergency', 'scientific', 'shared', 'emergency', 'guideline', '🧒', '{"en":"Danger signs in a child (2 months – 5 years)","bn":"শিশুর বিপদচিহ্ন (২ মাস – ৫ বছর)"}'::jsonb, '{"en":"Any of these general danger signs means the child needs urgent care.","bn":"এর যেকোনো একটি সাধারণ বিপদচিহ্ন থাকলে শিশুর জরুরি চিকিৎসা দরকার।"}'::jsonb, '{"signs":{"en":["Not able to drink or breastfeed","Vomits everything","Has had fits (convulsions) with this illness","Unusually sleepy, floppy or unconscious","Chest pulling in, noisy breathing when calm, or very fast breathing","A baby under 3 months with a temperature of 38 °C or more"],"bn":["পান করতে বা বুকের দুধ খেতে পারছে না","যা খায় সব বমি করে","এই অসুখে খিঁচুনি হয়েছে","অস্বাভাবিক ঘুমঘুম, নেতিয়ে পড়া বা অজ্ঞান","বুক ভেতরে ঢুকে যাওয়া, শান্ত অবস্থায়ও শব্দ করে শ্বাস, বা খুব দ্রুত শ্বাস","৩ মাসের কম বয়সী শিশুর তাপমাত্রা ৩৮ °সে বা বেশি"]},"do_now":{"en":["Go to the nearest hospital now","Keep giving breast milk or sips of fluid if the child can drink","Take the vaccine card and any medicines with you"],"bn":["এখনই নিকটস্থ হাসপাতালে যান","শিশু পান করতে পারলে বুকের দুধ বা অল্প অল্প তরল দিতে থাকুন","টিকা কার্ড ও ব্যবহৃত ওষুধ সাথে নিন"]},"avoid":{"en":["Do not wait to see if the fever settles","Do not force food or drink into a child who is fitting or very sleepy"],"bn":["জ্বর কমে কিনা দেখার জন্য অপেক্ষা করবেন না","খিঁচুনি চলাকালীন বা খুব ঘুমঘুম শিশুকে জোর করে খাওয়াবেন না"]}}'::jsonb, 61, 1826, 'in_review'::lp_review_status, 3),
  ('emergency-pregnancy', 'emergency', 'scientific', 'shared', 'emergency', 'guideline', '🤰', '{"en":"Pregnancy danger signs","bn":"গর্ভাবস্থার বিপদচিহ্ন"}'::jsonb, '{"en":"Go to a hospital immediately — day or night — if any of these happen.","bn":"এর যেকোনোটি হলে দিন হোক বা রাত — সাথে সাথে হাসপাতালে যান।"}'::jsonb, '{"signs":{"en":["Bleeding from the vagina","Fits (convulsions)","Severe headache with blurred vision","Fever and too weak to get out of bed","Severe pain in the belly","Fast or difficult breathing","The baby moves less than usual or stops moving","Water breaks before labour pains start","Sudden swelling of the face and hands"],"bn":["যোনিপথে রক্তপাত","খিঁচুনি","ঝাপসা দেখার সাথে তীব্র মাথাব্যথা","জ্বর এবং বিছানা থেকে উঠতে না পারার মতো দুর্বলতা","পেটে তীব্র ব্যথা","দ্রুত বা কষ্ট করে শ্বাস","শিশুর নড়াচড়া স্বাভাবিকের চেয়ে কম বা বন্ধ","প্রসববেদনা শুরুর আগেই পানি ভাঙা","হঠাৎ মুখ ও হাত ফুলে যাওয়া"]},"do_now":{"en":["Go to the hospital now with your antenatal card","Use the transport and blood donor from your birth plan","Call 999 if you cannot get there"],"bn":["গর্ভকালীন কার্ড নিয়ে এখনই হাসপাতালে যান","প্রসব পরিকল্পনার যানবাহন ও রক্তদাতাকে কাজে লাগান","যেতে না পারলে ৯৯৯-এ ফোন করুন"]},"avoid":{"en":["Do not wait for the next check-up","Do not take medicines on your own"],"bn":["পরের চেকআপের অপেক্ষা করবেন না","নিজে নিজে ওষুধ খাবেন না"]}}'::jsonb, -280, 0, 'in_review'::lp_review_status, 4),
  ('emergency-after-birth-mother', 'emergency', 'scientific', 'mother', 'emergency', 'guideline', '🌷', '{"en":"Mother''s danger signs after birth","bn":"প্রসবের পর মায়ের বিপদচিহ্ন"}'::jsonb, '{"en":"The six weeks after birth carry real risks for the mother. These signs need a hospital now.","bn":"জন্মের পরের ছয় সপ্তাহ মায়ের জন্য ঝুঁকিপূর্ণ। এই লক্ষণগুলো দেখা দিলে এখনই হাসপাতালে যান।"}'::jsonb, '{"signs":{"en":["Heavy bleeding — soaking a pad in an hour, or large clots","Fits (convulsions)","Severe headache or blurred vision","Fever, chills, or bad-smelling discharge","Severe belly pain","Trouble breathing or chest pain","A painful, swollen, red leg (one side)","Thoughts of harming yourself or the baby"],"bn":["অতিরিক্ত রক্তপাত — এক ঘণ্টায় একটি প্যাড ভিজে যাওয়া বা বড় রক্তের দলা","খিঁচুনি","তীব্র মাথাব্যথা বা ঝাপসা দেখা","জ্বর, কাঁপুনি বা দুর্গন্ধযুক্ত স্রাব","পেটে তীব্র ব্যথা","শ্বাসকষ্ট বা বুকে ব্যথা","এক পায়ে ব্যথা, ফোলা ও লালচে ভাব","নিজের বা শিশুর ক্ষতি করার চিন্তা"]},"do_now":{"en":["Go to the hospital now; someone should go with you","If thoughts of harm come, do not stay alone — tell a family member now"],"bn":["এখনই হাসপাতালে যান; কেউ যেন সাথে থাকে","ক্ষতির চিন্তা এলে একা থাকবেন না — এখনই পরিবারের কাউকে বলুন"]},"avoid":{"en":["Do not wait for the bleeding to stop by itself","Do not feel ashamed to ask for help — this is an illness, not a weakness"],"bn":["রক্তপাত নিজে থেকে থামবে ভেবে অপেক্ষা করবেন না","সাহায্য চাইতে লজ্জা পাবেন না — এটি অসুখ, দুর্বলতা নয়"]}}'::jsonb, 0, 42, 'in_review'::lp_review_status, 5)
