INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('plan_folic_acid', '{"en":"Take folic acid as advised","bn":"পরামর্শমতো ফলিক অ্যাসিড খান"}'::jsonb, '{}'::jsonb, '{"en":"Folic acid taken before conception and in early pregnancy lowers the chance of neural tube defects such as spina bifida.","bn":"গর্ভধারণের আগে ও গর্ভাবস্থার শুরুতে ফলিক অ্যাসিড খেলে স্পাইনা বিফিডার মতো নিউরাল টিউবের ত্রুটির ঝুঁকি কমে।"}'::jsonb, '{"en":"Your baby''s brain and spine get the best start from the very first weeks.","bn":"প্রথম সপ্তাহ থেকেই শিশুর মস্তিষ্ক ও মেরুদণ্ড সবচেয়ে ভালো শুরু পায়।"}'::jsonb, '[]'::jsonb, '{"en":"Ask your doctor about the right dose, especially if you have epilepsy, diabetes or a previous pregnancy affected by a neural tube defect.","bn":"সঠিক মাত্রা ডাক্তারকে জিজ্ঞেস করুন, বিশেষ করে মৃগী, ডায়াবেটিস বা আগের গর্ভে নিউরাল টিউব ত্রুটি থাকলে।"}'::jsonb, 'recommended', 'daily', 'mother', 'planning', NULL, NULL, 1, 5, '💊', 'preconception_care', NULL, NULL, 'any', 'in_review'::lp_review_status, 10),
  ('plan_preconception_checkup', '{"en":"Book a pre-pregnancy check-up","bn":"গর্ভধারণের আগে চেকআপ করান"}'::jsonb, '{}'::jsonb, '{"en":"A check-up finds conditions such as anaemia, high blood pressure or diabetes that are best managed before pregnancy.","bn":"চেকআপে রক্তস্বল্পতা, উচ্চ রক্তচাপ বা ডায়াবেটিসের মতো সমস্যা ধরা পড়ে, যা গর্ভধারণের আগেই নিয়ন্ত্রণ করা ভালো।"}'::jsonb, '{"en":"You start pregnancy knowing your health and with a plan.","bn":"নিজের স্বাস্থ্য জেনে ও পরিকল্পনা নিয়ে গর্ভধারণ শুরু করবেন।"}'::jsonb, '[{"en":"Write down any illnesses, operations and medicines you both have.","bn":"দুজনের অসুখ, অপারেশন ও ওষুধের তালিকা লিখুন।"},{"en":"Ask about vaccines (such as Td) and blood tests.","bn":"টিকা (যেমন টিডি) ও রক্ত পরীক্ষার কথা জিজ্ঞেস করুন।"},{"en":"Ask which medicines are safe to continue.","bn":"কোন ওষুধ চালিয়ে যাওয়া নিরাপদ তা জিজ্ঞেস করুন।"}]'::jsonb, '{}'::jsonb, 'must_do', 'once', 'shared', 'planning', NULL, NULL, 60, 20, '🩺', 'preconception_care', NULL, NULL, 'any', 'in_review'::lp_review_status, 11),
  ('plan_couple_talk', '{"en":"Talk together about your plans","bn":"পরিকল্পনা নিয়ে দুজনে কথা বলুন"}'::jsonb, '{}'::jsonb, '{"en":"Agreeing on money, roles, family support and expectations early reduces stress later.","bn":"অর্থ, দায়িত্ব, পারিবারিক সহায়তা ও প্রত্যাশা নিয়ে আগে একমত হলে পরে চাপ কমে।"}'::jsonb, '{"en":"A calmer home and a shared plan before the baby comes.","bn":"শিশু আসার আগেই শান্ত পরিবেশ ও একসাথে তৈরি পরিকল্পনা।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'weekly', 'shared', 'planning', NULL, NULL, 20, 10, '❤️', 'couple_preparation', NULL, NULL, 'any', 'in_review'::lp_review_status, 12),
  ('preg_antenatal_contact', '{"en":"Keep your antenatal check-ups","bn":"গর্ভকালীন চেকআপ মিস করবেন না"}'::jsonb, '{}'::jsonb, '{"en":"WHO recommends at least eight antenatal contacts. Check-ups find problems like high blood pressure, anaemia or poor growth early.","bn":"বিশ্ব স্বাস্থ্য সংস্থা অন্তত আটবার গর্ভকালীন সেবা নেওয়ার পরামর্শ দেয়। চেকআপে উচ্চ রক্তচাপ, রক্তস্বল্পতা বা শিশুর কম বৃদ্ধি আগেভাগে ধরা পড়ে।"}'::jsonb, '{"en":"Safer pregnancy for mother and baby, with problems caught early.","bn":"সমস্যা আগে ধরা পড়ায় মা ও শিশুর জন্য নিরাপদ গর্ভাবস্থা।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'must_do', 'monthly', 'shared', 'pregnancy', -280, 0, 90, 20, '🩺', 'antenatal_care', NULL, NULL, 'any', 'in_review'::lp_review_status, 20),
  ('preg_supplements', '{"en":"Take iron and folic acid as prescribed","bn":"পরামর্শমতো আয়রন ও ফলিক অ্যাসিড খান"}'::jsonb, '{}'::jsonb, '{"en":"Pregnancy needs more iron and folic acid; they help prevent anaemia in the mother and low birth weight.","bn":"গর্ভাবস্থায় বেশি আয়রন ও ফলিক অ্যাসিড লাগে; এগুলো মায়ের রক্তস্বল্পতা ও শিশুর কম জন্মওজন প্রতিরোধে সাহায্য করে।"}'::jsonb, '{"en":"More energy for you and healthier growth for your baby.","bn":"আপনার শক্তি বাড়ে, শিশুর বৃদ্ধি ভালো হয়।"}'::jsonb, '[]'::jsonb, '{"en":"Take only what your health worker prescribed.","bn":"শুধু স্বাস্থ্যকর্মীর দেওয়া মাত্রায় খাবেন।"}'::jsonb, 'recommended', 'daily', 'mother', 'pregnancy', -280, 0, 1, 5, '💊', 'antenatal_care', NULL, NULL, 'any', 'in_review'::lp_review_status, 21),
  ('preg_learn_danger_signs', '{"en":"Learn the pregnancy danger signs — both of you","bn":"গর্ভাবস্থার বিপদচিহ্ন শিখুন — দুজনেই"}'::jsonb, '{}'::jsonb, '{"en":"Bleeding, fits, severe headache or less movement from the baby need a hospital at once. Knowing them saves time.","bn":"রক্তপাত, খিঁচুনি, তীব্র মাথাব্যথা বা শিশুর নড়াচড়া কমে গেলে সাথে সাথে হাসপাতালে যেতে হয়। আগে জানা থাকলে সময় বাঁচে।"}'::jsonb, '{"en":"You will recognise an emergency and act quickly.","bn":"জরুরি অবস্থা চিনে দ্রুত ব্যবস্থা নিতে পারবেন।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'learn', 'once', 'shared', 'pregnancy', -280, 0, 5, 20, '🚨', 'emergency', 'emergency-pregnancy', NULL, 'any', 'in_review'::lp_review_status, 22),
  ('preg_father_support', '{"en":"Ask how she feels and take over one household job this week","bn":"তিনি কেমন আছেন জিজ্ঞেস করুন এবং এ সপ্তাহে ঘরের একটি কাজ নিজে নিন"}'::jsonb, '{}'::jsonb, '{"en":"Support from the father lowers the mother''s stress and tiredness during pregnancy.","bn":"বাবার সহায়তা গর্ভাবস্থায় মায়ের মানসিক চাপ ও ক্লান্তি কমায়।"}'::jsonb, '{"en":"A rested mother and a stronger bond between you.","bn":"মা বিশ্রাম পান, আপনাদের বন্ধন আরও দৃঢ় হয়।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'weekly', 'father', 'pregnancy', -280, 0, 30, 10, '🤝', 'fatherhood', NULL, NULL, 'any', 'in_review'::lp_review_status, 23),
  ('preg_baby_movements', '{"en":"Notice your baby''s movements today","bn":"আজ শিশুর নড়াচড়া খেয়াল করুন"}'::jsonb, '{}'::jsonb, '{"en":"From the third trimester you get to know your baby''s usual pattern. A change can be an early warning.","bn":"তৃতীয় তিন মাস থেকে শিশুর স্বাভাবিক নড়াচড়ার ধরন বোঝা যায়। পরিবর্তন আগাম সতর্কসংকেত হতে পারে।"}'::jsonb, '{"en":"You know what is normal for your baby.","bn":"আপনার শিশুর জন্য কোনটা স্বাভাবিক তা জানবেন।"}'::jsonb, '[]'::jsonb, '{"en":"If your baby moves less than usual or stops moving, contact your health facility the same day — do not wait until tomorrow.","bn":"শিশু স্বাভাবিকের চেয়ে কম নড়লে বা নড়াচড়া বন্ধ হলে সেদিনই স্বাস্থ্যকেন্দ্রে যোগাযোগ করুন — পরের দিনের অপেক্ষা করবেন না।"}'::jsonb, 'observe', 'daily', 'mother', 'pregnancy', -84, 0, 5, 5, '🦋', 'fetal_development', NULL, NULL, 'any', 'in_review'::lp_review_status, 24),
  ('preg_birth_plan', '{"en":"Make a birth plan","bn":"প্রসব পরিকল্পনা করুন"}'::jsonb, '{}'::jsonb, '{"en":"Deciding where to give birth, who will come and how you will get there avoids delays when labour starts.","bn":"কোথায় প্রসব হবে, কে সাথে যাবে, কীভাবে যাবেন — আগে ঠিক থাকলে প্রসববেদনা শুরু হলে দেরি হয় না।"}'::jsonb, '{"en":"A calmer, safer birth day.","bn":"শান্ত ও নিরাপদ প্রসবের দিন।"}'::jsonb, '[{"en":"Choose a facility with a skilled birth attendant.","bn":"দক্ষ প্রসব সহায়তাকারী আছে এমন স্বাস্থ্যকেন্দ্র বেছে নিন।"},{"en":"Arrange transport for day and night.","bn":"দিন ও রাতের জন্য যানবাহন ঠিক করুন।"},{"en":"Keep money aside for emergencies.","bn":"জরুরি খরচের টাকা আলাদা রাখুন।"},{"en":"Find a blood donor with a matching blood group.","bn":"একই রক্তের গ্রুপের রক্তদাতা ঠিক করুন।"}]'::jsonb, '{}'::jsonb, 'recommended', 'once', 'shared', 'pregnancy', -84, 0, 30, 20, '📝', 'birth_preparation', NULL, NULL, 'any', 'in_review'::lp_review_status, 25),
  ('preg_hospital_bag', '{"en":"Pack the hospital bag","bn":"হাসপাতালের ব্যাগ গুছিয়ে রাখুন"}'::jsonb, '{}'::jsonb, '{"en":"A packed bag means nothing important is forgotten when you have to leave quickly.","bn":"ব্যাগ গোছানো থাকলে তাড়াহুড়োয় জরুরি কিছু ভুলে যাবেন না।"}'::jsonb, '{"en":"Ready to go at any hour.","bn":"যেকোনো সময় রওনা দিতে প্রস্তুত।"}'::jsonb, '[{"en":"Mother: antenatal card, reports, clothes, pads, toiletries.","bn":"মা: গর্ভকালীন কার্ড, রিপোর্ট, কাপড়, প্যাড, প্রসাধনী।"},{"en":"Baby: soft clothes, cap, socks, wrapping cloths, nappies.","bn":"শিশু: নরম জামা, টুপি, মোজা, কাঁথা, ডায়াপার।"},{"en":"Companion: phone charger, money, ID, phone numbers.","bn":"সঙ্গী: ফোন চার্জার, টাকা, পরিচয়পত্র, ফোন নম্বর।"}]'::jsonb, '{}'::jsonb, 'recommended', 'once', 'shared', 'pregnancy', -56, 0, 30, 15, '🧳', 'birth_preparation', NULL, NULL, 'any', 'in_review'::lp_review_status, 26),
  ('newborn_safe_sleep', '{"en":"Put baby to sleep on their back, on a firm flat surface","bn":"শিশুকে চিত করে, শক্ত সমান জায়গায় ঘুম পাড়ান"}'::jsonb, '{}'::jsonb, '{"en":"Sleeping on the back, without pillows or soft bedding near the face, lowers the risk of sudden infant death.","bn":"চিত হয়ে ঘুমালে এবং মুখের কাছে বালিশ বা নরম বিছানা না থাকলে হঠাৎ শিশুমৃত্যুর ঝুঁকি কমে।"}'::jsonb, '{"en":"Safer sleep, every sleep.","bn":"প্রতিবার নিরাপদ ঘুম।"}'::jsonb, '[{"en":"Back to sleep for naps and at night.","bn":"দিনে ও রাতে — সবসময় চিত করে।"},{"en":"No pillows, toys or loose blankets near the face.","bn":"মুখের কাছে বালিশ, খেলনা বা ঢিলে কাঁথা নয়।"},{"en":"Keep baby in your room, close to you.","bn":"শিশুকে আপনার ঘরে, কাছাকাছি রাখুন।"}]'::jsonb, '{}'::jsonb, 'must_do', 'daily', 'shared', 'child', 0, 365, 1, 5, '😴', 'sleep', NULL, NULL, 'any', 'in_review'::lp_review_status, 30),
  ('newborn_feeding_cues', '{"en":"Watch for early hunger cues","bn":"খিদের প্রথম লক্ষণগুলো খেয়াল করুন"}'::jsonb, '{}'::jsonb, '{"en":"Rooting, sucking on hands and stirring come before crying. Feeding at these cues makes latching easier.","bn":"মুখ ঘোরানো, হাত চোষা ও নড়াচড়া — এগুলো কান্নার আগে আসে। এ সময়ে খাওয়ালে স্তন মুখে নেওয়া সহজ হয়।"}'::jsonb, '{"en":"Calmer feeds and a baby who feeds well.","bn":"শান্তভাবে খাওয়ানো, শিশু ভালোভাবে খায়।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'observe', 'daily', 'mother', 'child', 0, 183, 5, 5, '🍼', 'breastfeeding', NULL, NULL, 'any', 'in_review'::lp_review_status, 31),
  ('newborn_cord_care', '{"en":"Keep the cord stump clean and dry","bn":"নাভি পরিষ্কার ও শুকনো রাখুন"}'::jsonb, '{}'::jsonb, '{"en":"A clean, dry cord heals on its own in about one to two weeks.","bn":"পরিষ্কার ও শুকনো রাখলে নাভি এক-দুই সপ্তাহে নিজেই শুকিয়ে পড়ে যায়।"}'::jsonb, '{"en":"Lower chance of cord infection.","bn":"নাভিতে সংক্রমণের ঝুঁকি কমে।"}'::jsonb, '[]'::jsonb, '{"en":"Follow your health worker''s advice (in Bangladesh, chlorhexidine is often given). Do not put oil, ash, turmeric or other things on the cord. Redness spreading around it, pus or a bad smell need a doctor.","bn":"স্বাস্থ্যকর্মীর পরামর্শ মানুন (বাংলাদেশে প্রায়ই ক্লোরহেক্সিডিন দেওয়া হয়)। নাভিতে তেল, ছাই, হলুদ বা অন্য কিছু লাগাবেন না। চারপাশে লালচে ভাব ছড়ালে, পুঁজ বা দুর্গন্ধ হলে ডাক্তার দেখান।"}'::jsonb, 'must_do', 'daily', 'any', 'child', 0, 14, 2, 5, '🩹', 'newborn_care', NULL, NULL, 'any', 'in_review'::lp_review_status, 32),
  ('newborn_skin_to_skin', '{"en":"Skin-to-skin time","bn":"ত্বকের সাথে ত্বকের ছোঁয়া"}'::jsonb, '{}'::jsonb, '{"en":"Holding baby on the bare chest keeps them warm, steadies breathing and helps breastfeeding.","bn":"খালি বুকে শিশুকে রাখলে উষ্ণ থাকে, শ্বাস-প্রশ্বাস স্থির হয় এবং বুকের দুধ খাওয়ানো সহজ হয়।"}'::jsonb, '{"en":"A warm, calm baby and a deeper bond — fathers can do it too.","bn":"উষ্ণ ও শান্ত শিশু, গভীর বন্ধন — বাবাও করতে পারেন।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 0, 91, 30, 10, '🤱', 'bonding', NULL, NULL, 'any', 'in_review'::lp_review_status, 33),
  ('infant_tummy_time', '{"en":"Tummy time while awake and watched","bn":"জেগে থাকা অবস্থায়, চোখে চোখে রেখে উপুড় করে খেলা"}'::jsonb, '{}'::jsonb, '{"en":"Short sessions on the tummy build neck, shoulder and arm strength for rolling, sitting and crawling.","bn":"অল্প সময় উপুড় করে রাখলে ঘাড়, কাঁধ ও হাত শক্ত হয় — যা গড়ানো, বসা ও হামাগুড়ির জন্য দরকার।"}'::jsonb, '{"en":"Stronger muscles and a fun time face to face.","bn":"শক্ত পেশি আর মুখোমুখি আনন্দের সময়।"}'::jsonb, '[]'::jsonb, '{"en":"Only while awake and someone is watching; always back to sleep.","bn":"শুধু জেগে থাকা অবস্থায় ও কেউ পাশে থাকলে; ঘুমের সময় সবসময় চিত করে।"}'::jsonb, 'recommended', 'daily', 'shared', 'child', 0, 183, 10, 5, '💪', 'development', NULL, 'who_activity_under5', 'any', 'in_review'::lp_review_status, 34),
  ('infant_talk_sing', '{"en":"Talk, sing and smile face to face","bn":"মুখোমুখি কথা বলুন, গান করুন, হাসুন"}'::jsonb, '{}'::jsonb, '{"en":"Back-and-forth talk builds the brain connections for language long before the first word.","bn":"আদান-প্রদানের কথাবার্তা প্রথম শব্দের অনেক আগেই ভাষার জন্য মস্তিষ্কের সংযোগ তৈরি করে।"}'::jsonb, '{"en":"Supports language and makes your baby feel safe and loved.","bn":"ভাষার বিকাশে সহায়তা করে এবং শিশু নিরাপদ ও ভালোবাসা অনুভব করে।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 0, 730, 10, 5, '🎶', 'language', NULL, NULL, 'any', 'in_review'::lp_review_status, 35),
  ('father_care_turn', '{"en":"Take one care job so the mother can rest","bn":"একটি যত্নের কাজ নিন, যাতে মা বিশ্রাম পান"}'::jsonb, '{}'::jsonb, '{"en":"Burping, changing nappies, bathing and settling the baby give the mother time to sleep and recover.","bn":"ঢেকুর তোলানো, ডায়াপার বদলানো, গোসল করানো ও ঘুম পাড়ানো — এতে মা ঘুমানো ও সেরে ওঠার সময় পান।"}'::jsonb, '{"en":"A rested mother and a father who knows his baby.","bn":"বিশ্রাম পাওয়া মা, আর শিশুকে কাছ থেকে চেনা বাবা।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'daily', 'father', 'child', 0, 183, 30, 10, '👨‍🍼', 'fatherhood', NULL, NULL, 'any', 'in_review'::lp_review_status, 36),
  ('mother_postnatal_checks', '{"en":"Go to the postnatal check-ups for mother and baby","bn":"মা ও শিশুর প্রসব-পরবর্তী চেকআপ করান"}'::jsonb, '{}'::jsonb, '{"en":"The first six weeks after birth are when many problems for mother and baby appear. WHO advises several check-ups in this time.","bn":"জন্মের পরের প্রথম ছয় সপ্তাহে মা ও শিশুর অনেক সমস্যা দেখা দেয়। এ সময়ে বিশ্ব স্বাস্থ্য সংস্থা কয়েকবার চেকআপের পরামর্শ দেয়।"}'::jsonb, '{"en":"Problems with bleeding, infection, feeding or jaundice are found early.","bn":"রক্তপাত, সংক্রমণ, খাওয়ানো বা জন্ডিসের সমস্যা আগে ধরা পড়ে।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'must_do', 'once', 'mother', 'child', 0, 42, 60, 20, '🩺', 'mother_recovery', NULL, 'who_postnatal_2022', 'any', 'in_review'::lp_review_status, 37),
  ('mother_rest_eat', '{"en":"Rest, eat well and drink enough","bn":"বিশ্রাম নিন, ভালো খান ও যথেষ্ট পানি পান করুন"}'::jsonb, '{}'::jsonb, '{"en":"Your body is healing and making milk. Rest and food help both.","bn":"আপনার শরীর সেরে উঠছে ও দুধ তৈরি করছে। বিশ্রাম ও খাবার দুটোতেই সাহায্য করে।"}'::jsonb, '{"en":"Faster recovery and more energy for your baby.","bn":"দ্রুত সেরে ওঠা ও শিশুর জন্য বেশি শক্তি।"}'::jsonb, '[]'::jsonb, '{"en":"Feeling low most days, or thoughts of harming yourself or the baby, need help now — tell someone and see a doctor.","bn":"বেশিরভাগ দিন মন খারাপ থাকলে, বা নিজের বা শিশুর ক্ষতির চিন্তা এলে এখনই সাহায্য নিন — কাউকে বলুন ও ডাক্তার দেখান।"}'::jsonb, 'recommended', 'daily', 'mother', 'child', 0, 42, 5, 5, '🌷', 'mother_recovery', NULL, NULL, 'any', 'in_review'::lp_review_status, 38),
  ('growth_measure', '{"en":"Record weight and length from the latest check-up","bn":"সর্বশেষ চেকআপের ওজন ও দৈর্ঘ্য লিখে রাখুন"}'::jsonb, '{}'::jsonb, '{"en":"A line of measurements over time shows how your child is growing; one number alone says little.","bn":"সময়ের সাথে মাপের ধারাবাহিকতা দেখায় শিশু কেমন বাড়ছে; একটি মাপ একা খুব কম বলে।"}'::jsonb, '{"en":"A growth chart you can show at every visit.","bn":"প্রতিবার ডাক্তারকে দেখানোর মতো বৃদ্ধির চার্ট।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'observe', 'monthly', 'shared', 'child', 0, 730, 10, 10, '📏', 'growth_tracking', NULL, NULL, 'any', 'in_review'::lp_review_status, 39),
  ('vaccine_card_check', '{"en":"Check the vaccine card for the next dose","bn":"টিকা কার্ডে পরের ডোজ দেখে নিন"}'::jsonb, '{}'::jsonb, '{"en":"Vaccines work best when given on time.","bn":"সময়মতো দিলে টিকা সবচেয়ে ভালো কাজ করে।"}'::jsonb, '{"en":"Your child is protected against serious diseases.","bn":"আপনার সন্তান মারাত্মক রোগ থেকে সুরক্ষিত থাকে।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'must_do', 'monthly', 'shared', 'child', 0, 730, 5, 10, '💉', 'vaccination', NULL, NULL, 'any', 'in_review'::lp_review_status, 40),
  ('learn_first_foods', '{"en":"Learn about first foods at around 6 months","bn":"৬ মাসের কাছাকাছি প্রথম খাবার সম্পর্কে জানুন"}'::jsonb, '{}'::jsonb, '{"en":"From about 6 months, breast milk alone is not enough. Solid foods are added while breastfeeding continues.","bn":"প্রায় ৬ মাস থেকে শুধু বুকের দুধ যথেষ্ট নয়। বুকের দুধ চালিয়ে যাওয়ার পাশাপাশি অন্য খাবার শুরু করতে হয়।"}'::jsonb, '{"en":"You will be ready with safe, nutritious first meals.","bn":"নিরাপদ ও পুষ্টিকর প্রথম খাবার নিয়ে প্রস্তুত থাকবেন।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'learn', 'once', 'shared', 'child', 152, 213, 10, 20, '🥣', 'complementary_feeding', NULL, 'who_iycf', 'any', 'in_review'::lp_review_status, 41),
  ('new_food_weekly', '{"en":"Offer one new food this week","bn":"এ সপ্তাহে একটি নতুন খাবার দিন"}'::jsonb, '{}'::jsonb, '{"en":"Variety gives more nutrients and helps children accept different tastes.","bn":"বৈচিত্র্য বেশি পুষ্টি দেয় এবং শিশুকে নানা স্বাদে অভ্যস্ত করে।"}'::jsonb, '{"en":"A child who eats a wider range of foods.","bn":"নানা রকম খাবার খেতে অভ্যস্ত শিশু।"}'::jsonb, '[]'::jsonb, '{"en":"Soft textures, no whole nuts or hard round pieces; always watch while eating.","bn":"নরম খাবার দিন, আস্ত বাদাম বা শক্ত গোল টুকরো নয়; খাওয়ার সময় সবসময় পাশে থাকুন।"}'::jsonb, 'recommended', 'weekly', 'shared', 'child', 183, 730, 15, 10, '🍌', 'complementary_feeding', NULL, NULL, 'any', 'in_review'::lp_review_status, 42),
  ('brush_teeth', '{"en":"Brush teeth twice today","bn":"আজ দুইবার দাঁত ব্রাশ করান"}'::jsonb, '{}'::jsonb, '{"en":"Cleaning from the first tooth with a smear of fluoride toothpaste prevents decay.","bn":"প্রথম দাঁত থেকেই সামান্য ফ্লোরাইড টুথপেস্ট দিয়ে পরিষ্কার করলে দাঁতের ক্ষয় প্রতিরোধ হয়।"}'::jsonb, '{"en":"Healthy teeth and a lifelong habit.","bn":"সুস্থ দাঁত ও সারাজীবনের অভ্যাস।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 183, 2557, 4, 5, '🦷', 'dental', NULL, NULL, 'any', 'in_review'::lp_review_status, 43),
  ('read_together', '{"en":"Read or look at a book together","bn":"একসাথে বই পড়ুন বা ছবি দেখুন"}'::jsonb, '{}'::jsonb, '{"en":"Shared reading builds vocabulary, attention and closeness.","bn":"একসাথে পড়া শব্দভান্ডার, মনোযোগ ও ঘনিষ্ঠতা বাড়ায়।"}'::jsonb, '{"en":"Supports language development and bonding.","bn":"ভাষার বিকাশ ও বন্ধনে সহায়তা করে।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 183, 4748, 15, 10, '📚', 'language', NULL, NULL, 'any', 'in_review'::lp_review_status, 44),
  ('name_feelings', '{"en":"Name a feeling with your child","bn":"সন্তানের সাথে একটি অনুভূতির নাম বলুন"}'::jsonb, '{}'::jsonb, '{"en":"\"You are angry because the tower fell\" — naming feelings helps children calm down and later use words instead of hitting.","bn":"\"টাওয়ার পড়ে গেছে বলে তুমি রাগ করেছ\" — অনুভূতির নাম বললে শিশু শান্ত হতে শেখে, পরে মারার বদলে কথায় বলে।"}'::jsonb, '{"en":"Fewer tantrums over time and better self-control.","bn":"সময়ের সাথে রাগের প্রকাশ কমে, আত্মনিয়ন্ত্রণ বাড়ে।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 730, 2557, 5, 5, '😤', 'emotions', NULL, NULL, 'any', 'in_review'::lp_review_status, 45),
  ('outdoor_play', '{"en":"Active play, outdoors if you can","bn":"সক্রিয় খেলা, সম্ভব হলে বাইরে"}'::jsonb, '{}'::jsonb, '{"en":"Young children need plenty of active play every day for strong bodies, sleep and mood.","bn":"শক্ত শরীর, ভালো ঘুম ও মেজাজের জন্য ছোট শিশুদের প্রতিদিন অনেক সক্রিয় খেলা দরকার।"}'::jsonb, '{"en":"Better sleep, stronger muscles and a happier child.","bn":"ভালো ঘুম, শক্ত পেশি ও খুশি শিশু।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 365, 4748, 30, 5, '🌳', 'physical_activity', NULL, 'who_activity_under5', 'any', 'in_review'::lp_review_status, 46),
  ('screen_time_check', '{"en":"Review this week''s screen time together","bn":"এ সপ্তাহের স্ক্রিন টাইম একসাথে দেখুন"}'::jsonb, '{}'::jsonb, '{"en":"WHO advises no more than one hour of sitting screen time a day for 2–4 year olds — less is better. Older children need clear family rules.","bn":"বিশ্ব স্বাস্থ্য সংস্থা ২–৪ বছরের শিশুদের দিনে এক ঘণ্টার বেশি বসে স্ক্রিন না দেখার পরামর্শ দেয় — কম হলে আরও ভালো। বড় শিশুদের জন্য পরিবারের স্পষ্ট নিয়ম দরকার।"}'::jsonb, '{"en":"More time for play, sleep and talking together.","bn":"খেলা, ঘুম ও গল্পের জন্য বেশি সময়।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'observe', 'weekly', 'shared', 'child', 730, 4748, 10, 10, '📱', 'digital_life', NULL, 'who_activity_under5', 'any', 'in_review'::lp_review_status, 47),
  ('family_dua', '{"en":"Say a short dua together","bn":"একসাথে একটি ছোট দোয়া পড়ুন"}'::jsonb, '{}'::jsonb, '{"en":"Children learn worship by hearing and seeing it at home — for example the dua before eating or sleeping.","bn":"শিশুরা ঘরে শুনে ও দেখে ইবাদত শেখে — যেমন খাওয়া বা ঘুমের আগের দোয়া।"}'::jsonb, '{"en":"Builds familiarity with Islamic practice in a warm way.","bn":"আন্তরিকভাবে ইসলামি চর্চার সাথে পরিচয় গড়ে ওঠে।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'family', NULL, NULL, 2, 5, '🤲', 'islamic_upbringing', NULL, NULL, 'any', 'in_review'::lp_review_status, 48),
  ('prophet_story', '{"en":"Tell a story of a prophet","bn":"একজন নবীর গল্প বলুন"}'::jsonb, '{}'::jsonb, '{"en":"Stories teach honesty, patience and kindness in a way children remember.","bn":"গল্প এমনভাবে সততা, ধৈর্য ও দয়া শেখায় যা শিশুরা মনে রাখে।"}'::jsonb, '{"en":"Character lessons and a weekly family ritual.","bn":"চরিত্র গঠনের শিক্ষা ও সাপ্তাহিক পারিবারিক অভ্যাস।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'weekly', 'shared', 'child', 1461, 4748, 15, 10, '📖', 'islamic_upbringing', NULL, NULL, 'any', 'in_review'::lp_review_status, 49),
  ('salah_together', '{"en":"Pray one salah together and invite your child","bn":"একসাথে এক ওয়াক্ত নামাজ পড়ুন ও সন্তানকে ডাকুন"}'::jsonb, '{}'::jsonb, '{"en":"The Prophet ﷺ told parents to teach children salah from seven (Abu Dawud 495). Gentle, regular practice builds the habit.","bn":"রাসূল ﷺ সাত বছর বয়স থেকে সন্তানদের নামাজ শেখাতে বলেছেন (আবু দাউদ ৪৯৫)। কোমল ও নিয়মিত অনুশীলন অভ্যাস গড়ে তোলে।"}'::jsonb, '{"en":"A prayer habit built with love, not pressure.","bn":"চাপ নয়, ভালোবাসায় গড়ে ওঠা নামাজের অভ্যাস।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 2557, 4748, 10, 10, '🕌', 'salah', NULL, 'hadith_abudawud_495', 'any', 'in_review'::lp_review_status, 50),
  ('teen_one_to_one', '{"en":"Spend 20 minutes one-to-one, mostly listening","bn":"২০ মিনিট একান্তে সময় দিন, বেশিরভাগ সময় শুনুন"}'::jsonb, '{}'::jsonb, '{"en":"Teenagers talk more when they feel heard rather than judged. Regular time keeps the door open for hard topics.","bn":"কিশোর-কিশোরীরা বিচার নয়, শোনা হচ্ছে মনে করলে বেশি কথা বলে। নিয়মিত সময় দিলে কঠিন বিষয়েও কথা বলার পথ খোলা থাকে।"}'::jsonb, '{"en":"Trust that lasts into adulthood.","bn":"প্রাপ্তবয়স্ক জীবন পর্যন্ত টিকে থাকা আস্থা।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'family', 'weekly', 'shared', 'child', 4748, 7305, 20, 15, '💬', 'positive_discipline', NULL, NULL, 'any', 'in_review'::lp_review_status, 51)
INSERT INTO lp_counter_templates (key, title, description, why, safety_note, emoji, unit, input, step, target, target_kind, period, subject, min_day, max_day, sex, xp, category_key, source_key, review_status, sort_order) VALUES
  ('kick_count', '{"en":"Baby''s movements","bn":"শিশুর নড়াচড়া"}'::jsonb, '{}'::jsonb, '{"en":"From week 28, knowing your baby''s usual pattern of movements helps you notice early if something changes.","bn":"২৮ সপ্তাহ থেকে শিশুর স্বাভাবিক নড়াচড়ার ধরন জানা থাকলে কোনো পরিবর্তন আগেভাগে টের পাওয়া যায়।"}'::jsonb, '{"en":"What matters most is your baby''s own usual pattern. If movements are fewer than usual or stop, contact your health facility the same day — do not wait.","bn":"সবচেয়ে জরুরি হলো আপনার শিশুর নিজের স্বাভাবিক ধরন। নড়াচড়া স্বাভাবিকের চেয়ে কম হলে বা বন্ধ হলে সেদিনই স্বাস্থ্যকেন্দ্রে যোগাযোগ করুন — অপেক্ষা করবেন না।"}'::jsonb, '🦋', 'times', 'tap', 1, 10, 'at_least', 'day', 'pregnancy', -84, 0, 'any', 5, 'fetal_development', NULL, 'in_review'::lp_review_status, 10),
  ('water_pregnancy', '{"en":"Glasses of water","bn":"পানি (গ্লাস)"}'::jsonb, '{}'::jsonb, '{"en":"Enough fluid helps with constipation, tiredness and swelling in pregnancy.","bn":"পর্যাপ্ত পানি গর্ভাবস্থায় কোষ্ঠকাঠিন্য, ক্লান্তি ও ফোলাভাব কমাতে সাহায্য করে।"}'::jsonb, '{"en":"If your doctor has asked you to limit fluids, follow that instead.","bn":"ডাক্তার পানি কম খেতে বললে সেটিই মেনে চলুন।"}'::jsonb, '💧', 'glasses', 'tap', 1, 8, 'at_least', 'day', 'pregnancy', -280, 0, 'any', 3, 'nutrition', NULL, 'in_review'::lp_review_status, 20),
  ('iron_tablet', '{"en":"Iron and folic acid tablet","bn":"আয়রন ও ফলিক অ্যাসিড ট্যাবলেট"}'::jsonb, '{}'::jsonb, '{"en":"Taken as prescribed, they help prevent anaemia in the mother and low birth weight.","bn":"পরামর্শমতো খেলে মায়ের রক্তস্বল্পতা ও শিশুর কম জন্মওজন প্রতিরোধে সাহায্য করে।"}'::jsonb, '{"en":"Take only the number your health worker prescribed.","bn":"স্বাস্থ্যকর্মী যত দিয়েছেন শুধু ততটিই খাবেন।"}'::jsonb, '💊', 'tablets', 'tap', 1, 1, 'at_least', 'day', 'pregnancy', -280, 0, 'any', 3, 'antenatal_care', NULL, 'in_review'::lp_review_status, 30),
  ('feeds', '{"en":"Feeds","bn":"খাওয়ানো"}'::jsonb, '{}'::jsonb, '{"en":"Young babies usually feed 8–12 times in 24 hours. Feeding when the baby shows hunger keeps the milk supply up.","bn":"ছোট শিশু সাধারণত ২৪ ঘণ্টায় ৮–১২ বার খায়। খিদের লক্ষণ দেখে খাওয়ালে দুধের পরিমাণও ঠিক থাকে।"}'::jsonb, '{"en":"A baby who is not feeding well or is too sleepy to feed needs to see a health worker today.","bn":"শিশু ঠিকমতো না খেলে বা খাওয়ার মতো জেগে না থাকলে আজই স্বাস্থ্যকর্মী দেখান।"}'::jsonb, '🍼', 'times', 'tap', 1, 8, 'at_least', 'day', 'child', 0, 183, 'any', 3, 'breastfeeding', 'who_iycf', 'in_review'::lp_review_status, 40),
  ('wet_nappies', '{"en":"Wet nappies","bn":"ভেজা ন্যাপি"}'::jsonb, '{}'::jsonb, '{"en":"After the first few days, 6 or more wet nappies a day is a simple sign the baby is getting enough milk.","bn":"প্রথম কয়েক দিনের পর দিনে ৬ বা তার বেশি ভেজা ন্যাপি শিশুর যথেষ্ট দুধ পাওয়ার সহজ লক্ষণ।"}'::jsonb, '{"en":"Fewer wet nappies, dark urine or a dry mouth can mean the baby is not getting enough — see a health worker.","bn":"ভেজা ন্যাপি কম, প্রস্রাব গাঢ় বা মুখ শুকনো হলে শিশু হয়তো যথেষ্ট পাচ্ছে না — স্বাস্থ্যকর্মী দেখান।"}'::jsonb, '🧷', 'times', 'tap', 1, 6, 'at_least', 'day', 'child', 5, 183, 'any', 3, 'newborn_care', NULL, 'in_review'::lp_review_status, 50),
  ('tummy_time', '{"en":"Tummy time","bn":"উপুড় করে খেলা"}'::jsonb, '{}'::jsonb, '{"en":"WHO advises at least 30 minutes a day on the tummy, spread through the day while awake, for babies not yet crawling.","bn":"হামাগুড়ি শুরু না করা শিশুর জন্য বিশ্ব স্বাস্থ্য সংস্থা দিনে অন্তত ৩০ মিনিট, জেগে থাকা অবস্থায় ভাগ করে, উপুড় করে রাখার পরামর্শ দেয়।"}'::jsonb, '{"en":"Only while awake and someone is watching; always on the back to sleep.","bn":"শুধু জেগে থাকা অবস্থায় ও কেউ পাশে থাকলে; ঘুমের সময় সবসময় চিত করে।"}'::jsonb, '💪', 'minutes', 'timer', 1, 30, 'at_least', 'day', 'child', 0, 365, 'any', 5, 'development', 'who_activity_under5', 'in_review'::lp_review_status, 60),
  ('sleep_newborn', '{"en":"Sleep (hours)","bn":"ঘুম (ঘণ্টা)"}'::jsonb, '{}'::jsonb, '{"en":"Babies up to 3 months usually sleep 14–17 hours a day, including naps.","bn":"৩ মাস পর্যন্ত শিশু সাধারণত দিনে ১৪–১৭ ঘণ্টা ঘুমায়, দিনের ঘুমসহ।"}'::jsonb, '{}'::jsonb, '😴', 'hours', 'amount', 0.5, 14, 'at_least', 'day', 'child', 0, 122, 'any', 0, 'sleep', 'who_activity_under5', 'in_review'::lp_review_status, 70),
  ('sleep_infant', '{"en":"Sleep (hours)","bn":"ঘুম (ঘণ্টা)"}'::jsonb, '{}'::jsonb, '{"en":"Babies of 4–11 months usually sleep 12–16 hours a day, including naps.","bn":"৪–১১ মাসের শিশু সাধারণত দিনে ১২–১৬ ঘণ্টা ঘুমায়, দিনের ঘুমসহ।"}'::jsonb, '{}'::jsonb, '😴', 'hours', 'amount', 0.5, 12, 'at_least', 'day', 'child', 122, 365, 'any', 0, 'sleep', 'who_activity_under5', 'in_review'::lp_review_status, 71),
  ('brush_teeth', '{"en":"Teeth brushed","bn":"দাঁত ব্রাশ"}'::jsonb, '{}'::jsonb, '{"en":"Twice a day with a little fluoride toothpaste prevents tooth decay.","bn":"দিনে দুইবার সামান্য ফ্লোরাইড টুথপেস্ট দিয়ে ব্রাশ করলে দাঁতের ক্ষয় প্রতিরোধ হয়।"}'::jsonb, '{}'::jsonb, '🦷', 'times', 'tap', 1, 2, 'at_least', 'day', 'child', 183, 4748, 'any', 3, 'dental', NULL, 'in_review'::lp_review_status, 80),
  ('reading_minutes', '{"en":"Reading together","bn":"একসাথে পড়া"}'::jsonb, '{}'::jsonb, '{"en":"A few minutes of shared reading every day builds words, attention and closeness.","bn":"প্রতিদিন কয়েক মিনিট একসাথে পড়লে শব্দভান্ডার, মনোযোগ ও ঘনিষ্ঠতা বাড়ে।"}'::jsonb, '{}'::jsonb, '📚', 'minutes', 'timer', 1, 15, 'at_least', 'day', 'child', 183, 4748, 'any', 5, 'language', NULL, 'in_review'::lp_review_status, 90),
  ('active_play_toddler', '{"en":"Active play","bn":"সক্রিয় খেলা"}'::jsonb, '{}'::jsonb, '{"en":"WHO advises at least 180 minutes of varied physical activity a day for 1–4 year olds, spread through the day.","bn":"১–৪ বছরের শিশুর জন্য বিশ্ব স্বাস্থ্য সংস্থা দিনে অন্তত ১৮০ মিনিট নানা রকম শারীরিক খেলার পরামর্শ দেয়, সারাদিনে ভাগ করে।"}'::jsonb, '{}'::jsonb, '🏃', 'minutes', 'timer', 1, 180, 'at_least', 'day', 'child', 365, 1826, 'any', 5, 'physical_activity', 'who_activity_under5', 'in_review'::lp_review_status, 100),
  ('active_play_child', '{"en":"Active play / sport","bn":"খেলাধুলা"}'::jsonb, '{}'::jsonb, '{"en":"Children and teenagers need about 60 minutes of moderate to vigorous activity a day.","bn":"শিশু-কিশোরদের দিনে প্রায় ৬০ মিনিট মাঝারি থেকে জোরালো শারীরিক কাজ দরকার।"}'::jsonb, '{}'::jsonb, '⚽', 'minutes', 'timer', 1, 60, 'at_least', 'day', 'child', 1826, 7305, 'any', 5, 'physical_activity', NULL, 'in_review'::lp_review_status, 101),
  ('screen_time_under2', '{"en":"Screen time","bn":"স্ক্রিন টাইম"}'::jsonb, '{}'::jsonb, '{"en":"WHO does not recommend sitting screen time for children under 2. Video calls with family are fine.","bn":"২ বছরের কম শিশুর বসে স্ক্রিন দেখা বিশ্ব স্বাস্থ্য সংস্থা সুপারিশ করে না। পরিবারের সাথে ভিডিও কল ঠিক আছে।"}'::jsonb, '{}'::jsonb, '📵', 'minutes', 'timer', 1, 0, 'at_most', 'day', 'child', 365, 730, 'any', 0, 'digital_life', 'who_activity_under5', 'in_review'::lp_review_status, 110),
  ('screen_time_2_4', '{"en":"Screen time","bn":"স্ক্রিন টাইম"}'::jsonb, '{}'::jsonb, '{"en":"For 2–4 year olds, WHO advises no more than one hour of sitting screen time a day — less is better.","bn":"২–৪ বছরের শিশুর জন্য বিশ্ব স্বাস্থ্য সংস্থা দিনে এক ঘণ্টার বেশি বসে স্ক্রিন না দেখার পরামর্শ দেয় — কম হলে আরও ভালো।"}'::jsonb, '{}'::jsonb, '📱', 'minutes', 'timer', 1, 60, 'at_most', 'day', 'child', 730, 1826, 'any', 0, 'digital_life', 'who_activity_under5', 'in_review'::lp_review_status, 111),
  ('teen_talk', '{"en":"One-to-one time","bn":"একান্তে সময়"}'::jsonb, '{}'::jsonb, '{"en":"Regular time where you mostly listen keeps a teenager talking to you about hard things.","bn":"নিয়মিত একান্ত সময়, যেখানে আপনি বেশি শোনেন, কিশোর-কিশোরীকে কঠিন বিষয়েও কথা বলতে সাহায্য করে।"}'::jsonb, '{}'::jsonb, '💬', 'minutes', 'timer', 1, 60, 'at_least', 'week', 'child', 4748, 7305, 'any', 10, 'positive_discipline', NULL, 'in_review'::lp_review_status, 120),
  ('sleep_teen', '{"en":"Sleep (hours)","bn":"ঘুম (ঘণ্টা)"}'::jsonb, '{}'::jsonb, '{"en":"Teenagers need about 8–10 hours of sleep for mood, learning and growth.","bn":"মেজাজ, পড়াশোনা ও বৃদ্ধির জন্য কিশোর-কিশোরীদের প্রায় ৮–১০ ঘণ্টা ঘুম দরকার।"}'::jsonb, '{}'::jsonb, '🌙', 'hours', 'amount', 0.5, 8, 'at_least', 'day', 'child', 4748, 7305, 'any', 0, 'sleep', NULL, 'in_review'::lp_review_status, 130)
