  ('knowledge_seeker', 'learning', '{"en":"Knowledge Seeker","bn":"জ্ঞান অন্বেষী"}'::jsonb, '{"en":"Ten guides marked as learned.","bn":"দশটি গাইড শেখা হিসেবে চিহ্নিত।"}'::jsonb, '📚', '{"kind":"resources_learned","count":10}'::jsonb, 50, 2),
