  ('bond_builder', 'family', '{"en":"Bond Builder","bn":"বন্ধন গড়ার কারিগর"}'::jsonb, '{"en":"Twenty family and bonding activities.","bn":"বিশটি পারিবারিক ও বন্ধনের কাজ।"}'::jsonb, '💗', '{"kind":"tasks_done","count":20,"task_type":"family"}'::jsonb, 50, 4),
  ('team_parents', 'family', '{"en":"Team Parents","bn":"টিম প্যারেন্টস"}'::jsonb, '{"en":"Shared family tasks done together, five times.","bn":"পাঁচবার একসাথে পারিবারিক কাজ করেছেন।"}'::jsonb, '🤝', '{"kind":"shared_tasks","count":5}'::jsonb, 60, 5),
  ('health_guardian', 'health_records', '{"en":"Health Guardian","bn":"স্বাস্থ্য অভিভাবক"}'::jsonb, '{"en":"Ten health records kept up to date.","bn":"দশটি স্বাস্থ্য রেকর্ড হালনাগাদ রেখেছেন।"}'::jsonb, '🩺', '{"kind":"records_added","count":10}'::jsonb, 50, 6),
  ('milestone_observer', 'development', '{"en":"Milestone Observer","bn":"মাইলফলক পর্যবেক্ষক"}'::jsonb, '{"en":"You noted ten milestones — observing, not racing.","bn":"দশটি মাইলফলক লিখে রেখেছেন — দৌড় নয়, পর্যবেক্ষণ।"}'::jsonb, '🔭', '{"kind":"milestones_observed","count":10}'::jsonb, 40, 7),
  ('values_virtues', 'islamic', '{"en":"Values & Virtues","bn":"মূল্যবোধ ও সদগুণ"}'::jsonb, '{"en":"Ten Islamic learning moments as a family.","bn":"পরিবারের সাথে দশটি ইসলামি শিক্ষার মুহূর্ত।"}'::jsonb, '🌙', '{"kind":"tasks_done","count":10,"category_key":"islamic_upbringing"}'::jsonb, 50, 8),
  ('steady_care', 'activities', '{"en":"Steady Care","bn":"নিয়মিত যত্ন"}'::jsonb, '{"en":"Thirty days with something done — missed days are fine.","bn":"ত্রিশ দিন কিছু না কিছু করেছেন — মাঝে বাদ গেলেও সমস্যা নেই।"}'::jsonb, '🌳', '{"kind":"streak_days","count":30}'::jsonb, 80, 9)
